"""Terminal width, styling, and display-width helpers."""
import os
import re
import unicodedata

ANSI = re.compile(r'\x1b\[[0-9;]*m')


def use_color(fd=1):
    force = os.environ.get('CLICOLOR_FORCE')
    if force is not None and force != '0':
        return True
    if 'NO_COLOR' in os.environ or os.environ.get('CLICOLOR') == '0':
        return False
    return os.isatty(fd)


def term_width(default=0):
    for fd in (1, 2, 0):
        try:
            width = os.get_terminal_size(fd).columns
            if width:
                return width
        except OSError:
            pass
    return default


def paint(text, codes, enabled=True):
    if enabled and codes and text:
        return '\x1b[' + codes + 'm' + text + '\x1b[0m'
    return text


def visible_width(text):
    text = ANSI.sub('', text)
    width = 0
    for ch in text:
        cat = unicodedata.category(ch)
        if cat in ('Mn', 'Me', 'Cf', 'Cc', 'Cs'):
            continue
        width += 2 if unicodedata.east_asian_width(ch) in ('W', 'F') else 1
    return width


def pad(text, width, right=False):
    spaces = ' ' * max(0, width - visible_width(text))
    return spaces + text if right else text + spaces


def lossy(text):
    return text.encode('utf-8', 'surrogateescape').decode('utf-8', 'replace')
PY
