"""The command-line interface and its help and validation messages."""
import os
import re
import sys
import textwrap
from terminal import paint, term_width, use_color, visible_width

DETAILS = 'dev ino nlink typ perm oct user uid group gid size blocks btime ctime mtime atime git'.split()
STANDARD = 'nlink typ perm user group size mtime'.split()
TYPES = 'dir symlink fifo socket block-device char-device file'.split()
SORTS = ('dev ino nlink typ cat user uid group gid size blocks btime ctime mtime atime name cname ext '
         'inode_ nlinks_ typ_ cat_ user_ uid_ group_ gid_ size_ blocks_ btime_ ctime_ mtime_ atime_ name_ cname_ ext_ none').split()
BOOL = ['true', 'false']
# short name, long name, value name, description, default, allowed values, section
OPTIONS = [
    ('h', 'help', None, "Print help (see more with '--help')", None, None, 'Options'),
    ('V', 'version', None, 'Print version', None, None, 'Options'),
    ('d', 'det', 'DETAILS', 'the data points to show about each node', 'none', DETAILS + ['none', 'std', 'all'], 'Detail view'),
    ('H', 'header', 'HEADER', 'show headers above columnar data', 'true', BOOL, 'Detail view'),
    ('u', 'unit', 'UNIT', 'the type of units to use for the node sizes', 'binary', ['binary', 'decimal', 'none'], 'Detail view'),
    ('g', 'grid', 'GRID', 'display node names in multiple columns', 'false', BOOL, 'Grid view'),
    ('D', 'down', 'DOWN', 'display node names column-first', 'false', BOOL, 'Grid view'),
    ('i', 'icon', 'ICON', 'display icons next to node names', 'true', BOOL, 'Presentation'),
    ('S', 'suffix', 'SUFFIX', 'display node type suffixes after the node name', 'true', BOOL, 'Presentation'),
    ('l', 'sym', 'SYM', 'show symlink targets', 'true', BOOL, 'Presentation'),
    ('c', 'collapse', 'COLLAPSE', 'show dependent nodes as children of their principal nodes', 'true', BOOL, 'Presentation'),
    ('a', 'align', 'ALIGN', 'align items accounting for leading dots', 'true', BOOL, 'Presentation'),
    ('t', 'typ', 'TYPES', 'the set of node types to include in the output', 'all', TYPES + ['none', 'all'], 'Filtering'),
    ('I', 'imp', 'IMP', 'the importance cutoff to dim or hide unimportant files', '0', None, 'Filtering'),
    ('e', 'exclude', 'EXCLUDE', 'the pattern of files to selectively hide from the output', None, None, 'Filtering'),
    ('o', 'only', 'ONLY', 'the pattern of files to exclusively show in the output', None, None, 'Filtering'),
    ('s', 'sort', 'SORT_BASES', 'the set of fields to sort by, trailing `_` reverses the direction', 'cat cname', SORTS, 'Sorting'),
]
LONG = {x[1]: x for x in OPTIONS}
SHORT = {x[0]: x for x in OPTIONS}


def jaro(a, b):
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    radius = max(0, max(len(a), len(b)) // 2 - 1)
    am, bm = [False] * len(a), [False] * len(b)
    for i, ch in enumerate(a):
        for j in range(max(0, i-radius), min(i+radius+1, len(b))):
            if not bm[j] and ch == b[j]:
                am[i] = bm[j] = True
                break
    n = sum(am)
    if not n:
        return 0.0
    aa = [c for c, m in zip(a, am) if m]
    bb = [c for c, m in zip(b, bm) if m]
    trans = sum(c != d for c, d in zip(aa, bb)) / 2
    return (n / len(a) + n / len(b) + (n - trans) / n) / 3


def suggestion(value, candidates):
    best, score = None, 0.7
    for candidate in candidates:
        s = jaro(value, candidate)
        if s > score:
            best, score = candidate, s
    return best


def option_label(opt, color=False, both=False):
    s, name, metavar = opt[:3]
    prefix = (paint('-' + s, '1', color) + ', ') if both else ''
    return prefix + paint('--' + name, '1', color) + (' <' + metavar + '>' if metavar else '')


def wrapped(text, width, indent='', first_indent=None):
    if first_indent is None:
        first_indent = indent
    return textwrap.fill(text, width=max(width, len(indent)+1), initial_indent=first_indent,
                         subsequent_indent=indent, break_long_words=False,
                         break_on_hyphens=False, replace_whitespace=False)


def help_text(long, prog, color):
    width = term_width(100)
    heading = lambda text: paint(text, '1', color) if False else (
        '\x1b[1m\x1b[4m' + text + '\x1b[0m' if color else text)
    intro = 'pls is a prettier and powerful ls(1) for the pros.'
    out = wrapped(intro, width)
    if color:
        out = out.replace('pls', paint('pls', '1;31', True), 1)
    out += '\n\n'
    if long:
        out += 'Read docs: https://pls.cli.rs/\nGet source: https://github.com/pls-rs/pls/\nSponsor: https://github.com/sponsors/dhruvkb/\n\n'
    out += heading('Usage:') + ' ' + paint(prog, '1', color) + ' [OPTIONS] [PATHS]...\n\n'
    out += heading('Arguments:') + '\n'
    if long:
        out += '  [PATHS]...\n'
        out += wrapped('the paths to list, each of which may be a file or directory', width, '          ') + '\n'
        out += '          \n          [default: .]\n'
    else:
        desc = 'the paths to list, each of which may be a file or directory [default: .]'
        out += wrapped(desc, width, '             ', '  [PATHS]...  ') + '\n'
    sections = ['Options', 'Detail view', 'Grid view', 'Presentation', 'Filtering', 'Sorting']
    for section in sections:
        out += '\n' + heading(section + ':') + '\n'
        options = [o for o in OPTIONS if o[6] == section]
        maxlabel = max(len(option_label(o, False, True)) for o in options)
        for index, opt in enumerate(options):
            short, name, metavar, desc, default, values, _ = opt
            if long and name == 'help':
                desc = "Print help (see a summary with '-h')"
            label = option_label(opt, color, True)
            if long:
                if index:
                    out += '\n'
                out += '  ' + label + '\n'
                out += wrapped(desc, width, '          ') + '\n'
                if default is not None or values:
                    out += '          \n'
                    if default is not None:
                        out += '          [default: ' + default + ']\n'
                    if values:
                        out += wrapped('[possible values: ' + ', '.join(values) + ']', width, '          ') + '\n'
            else:
                desc += (' [default: ' + default + ']') if default is not None else ''
                desc += (' [possible values: ' + ', '.join(values) + ']') if values else ''
                prefix = '  ' + label + ' ' * (maxlabel - len(option_label(opt, False, True)) + 2)
                plainprefix = ' ' * (maxlabel + 4)
                lines = wrapped(desc, width, plainprefix).split('\n')
                out += prefix + lines[0][len(plainprefix):] + '\n'
                out += ''.join(line + '\n' for line in lines[1:])
    return out


class ArgumentError(Exception):
    def __init__(self, text):
        self.text = text


class Parser:
    def __init__(self, prog):
        self.prog = prog
        self.seen = []
        self.paths = []
        self.color = use_color(2)
        self.values = {o[1]: o[4] for o in OPTIONS if o[4] is not None}
        self.lists = {}

    def c(self, text, code):
        return paint(text, code, self.color)

    def usage(self, extra=None):
        seen = self.seen[:]
        if extra and extra not in seen:
            seen.append(extra)
        out = ('\x1b[1m\x1b[4mUsage:\x1b[0m' if self.color else 'Usage:')
        out += ' ' + self.c(self.prog, '1')
        if not seen and not self.paths:
            out += ' [OPTIONS]'
        for key in seen:
            out += ' ' + option_label(LONG[key], self.color)
        out += ' <PATHS>...' if self.paths else ' [PATHS]...'
        return out

    def fail(self, message, usage=False, extra=None):
        result = self.c('error:', '1') if False else (
            '\x1b[1m\x1b[31merror:\x1b[0m' if self.color else 'error:')
        result += ' ' + message
        if usage:
            result += '\n\n' + self.usage(extra)
        result += "\n\nFor more information, try '" + self.c('--help', '1') + "'.\n"
        raise ArgumentError(result)

    def unknown(self, arg):
        # Long-option suggestions compare the names rather than their dashes.
        cand = suggestion(arg[2:].split('=',1)[0], LONG) if arg.startswith('--') else None
        message = "unexpected argument '" + self.c(arg, '33') + "' found"
        if cand:
            message += "\n\n  " + self.c('tip:', '32') + " a similar argument exists: '" + self.c('--'+cand, '32') + "'"
        else:
            message += "\n\n  " + self.c('tip:', '32') + " to pass '" + self.c(arg, '33') + "' as a value, use '" + self.c('-- '+arg, '32') + "'"
        self.fail(message, True, cand)

    def missing(self, opt):
        label = '[PATHS]...' if opt is None else option_label(opt)
        msg = "a value is required for '" + self.c(label, '33') + "' but none was supplied"
        if opt and opt[5]:
            msg += '\n  [possible values: ' + ', '.join(self.c(v,'32') for v in opt[5]) + ']'
        self.fail(msg)

    def invalid(self, opt, value, reason=None):
        label = option_label(opt)
        if reason is not None:
            self.fail("invalid value '" + self.c(value,'33') + "' for '" + self.c(label,'1') + "': " + reason)
        msg = "invalid value '" + self.c(value, '33') + "' for '" + self.c(label, '1') + "'"
        msg += '\n  [possible values: ' + ', '.join(self.c(v, '32') for v in opt[5]) + ']'
        cand = suggestion(value, opt[5])
        if cand:
            msg += "\n\n  " + self.c('tip:', '32') + " a similar value exists: '" + self.c(cand,'32') + "'"
        self.fail(msg)

    def accept(self, opt, value):
        key = opt[1]
        if opt[5] is not None:
            if value == '':
                self.missing(opt)
            if value not in opt[5]:
                self.invalid(opt, value)
        if key == 'imp':
            if value == '':
                self.invalid(opt, value, 'cannot parse integer from empty string')
            if re.fullmatch(r'[+-]?[0-9]+', value) is None:
                self.invalid(opt, value, 'invalid digit found in string')
            number = int(value)
            if number > 9223372036854775807:
