            value = group_name(st.st_gid) if field=='group' else str(st.st_gid)
            return self.c(value,'2')
        if field == 'size': return '' if node.typ=='dir' else self.size(st.st_size)
        if field == 'blocks': return '' if node.typ=='dir' else str(st.st_blocks)
        if field == 'btime': return self.timestamp(node.btime(),field)
        if field in ('ctime','mtime','atime'): return self.timestamp(getattr(st,'st_'+field+'_ns'),field)
        if field == 'git': return ''
        return ''

    def render_grid(self, names):
        if not names:
            return ''
        width = term_width()
        maxwidth = max(visible_width(name) for name in names)
        n = len(names)
        maxcols = max(1, (width+2) // (maxwidth+2))
        rows = math.ceil(n/maxcols)
        cols = math.ceil(n/rows)
        if cols <= 1:
            return ''.join(name+'\n' for name in names)
        result = ''
        for row in range(rows):
            cells = []
            for col in range(cols):
                index = col*rows+row if self.options['down'] else row*cols+col
                if index < n:
                    cells.append(pad(names[index],maxwidth))
            result += '  '.join(cells) + '\n'
        return result

    def render(self, nodes, directory=False):
        fields = self.options['det']
        names = []
        allnodes = []
        for node in nodes:
            allnodes.append(node)
            names.append(self.name(node, directory))
            for child in node.children:
                allnodes.append(child)
                indent = ('   ' if self.options['align'] else '  ') + '└─ '
                names.append(indent + self.name(child,directory))
        if self.grid:
            return self.render_grid(names)
        if not fields:
            return ''.join(name+'\n' for name in names)
        show_header = self.options['header']
        data = [[self.value(node,field) for field in fields] for node in allnodes]
        widths = [len(HEADERS[f]) if show_header else 0 for f in fields]
        for row in data:
            for i,cell in enumerate(row):
                widths[i] = max(widths[i],visible_width(cell))
        out = ''
        if show_header:
            for i,field in enumerate(fields):
                label = pad(HEADERS[field],widths[i],field in NUMERIC) + ' '
                out += self.c(label, '1;4;3')
            out += self.c('Name', '1;4;3') + '\n'
        for row,name in zip(data,names):
            out += ''.join(pad(value,widths[i],fields[i] in NUMERIC)+' ' for i,value in enumerate(row))
            out += name + '\n'
        return out

    def directory(self, path):
        opts = self.options
        nodes = []
        try:
            entries = os.scandir(path)
        except OSError as err:
            return self.c('error:','1;31') + ' ' + os_error(err) + '\n'
        with entries:
            for entry in entries:
                try:
                    node = Node(entry.path,entry.name,entry.stat(follow_symlinks=False))
                except OSError:
                    continue
                if node.typ not in opts['typ']:
                    continue
                if effective_importance(node.name,opts['imp']) < -1:
                    continue
                if opts.get('exclude') and opts['exclude'].search(node.name):
                    continue
                if opts.get('only') and not opts['only'].search(node.name):
                    continue
                nodes.append(node)
        sort_nodes(nodes,opts['sort'])
        if opts['collapse'] and not self.grid:
            principal = next((node for node in nodes if node.name=='Cargo.toml'),None)
            dependent = next((node for node in nodes if node.name=='Cargo.lock'),None)
            if principal is not None and dependent is not None:
                nodes.remove(dependent)
                principal.children.append(dependent)
        return self.render(nodes,True)

    def run(self, paths):
        files = []
        dirs = []
        out = ''
        for path in paths:
            try:
                node = Node(path)
                if node.typ == 'dir':
                    dirs.append(path)
                else:
                    files.append(node)
            except OSError as err:
                out += self.c(lossy(path),'1') + ':\n\t' + self.c('error:','1;31') + ' ' + os_error(err) + '\n'
        if files:
            out += self.render(files,False)
        for directory in dirs:
            if len(paths)>1:
                out += '\n' + self.c(lossy(directory)+':','1') + '\n'
            out += self.directory(directory)
        return out
