#!/usr/bin/env python3
"""Entry point for the standalone directory lister."""
import os
import sys
from cli import Parser, ArgumentError
from listing import Renderer


def main():
    prog = os.path.basename(sys.argv[0]) or 'executable'
    try:
        options, paths = Parser(prog).parse(sys.argv[1:])
    except ArgumentError as err:
        sys.stderr.write(err.text)
        return 2
    try:
        output = Renderer(options).run(paths)
        sys.stdout.write(output)
        sys.stdout.flush()
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except OSError:
            pass
        return 0
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
