    _libc = ctypes.CDLL(None, use_errno=True)
    _statx = _libc.statx
    _statx.argtypes = [ctypes.c_int,ctypes.c_char_p,ctypes.c_int,ctypes.c_uint,ctypes.POINTER(Statx)]
    _statx.restype = ctypes.c_int
except (AttributeError, OSError):
    _statx = None


def birth_time(path):
    if _statx is None:
        return None
    info = Statx()
    if _statx(-100, os.fsencode(path), 0x100, 0x800, ctypes.byref(info)) == 0 and info.mask & 0x800:
        return info.btime.sec * 1000000000 + info.btime.nsec
    return None


@functools.lru_cache(maxsize=256)
def user_name(uid):
    try:
        return pwd.getpwuid(uid).pw_name
    except KeyError:
        return str(uid)


@functools.lru_cache(maxsize=256)
def group_name(gid):
    try:
        return grp.getgrgid(gid).gr_name
    except KeyError:
        return str(gid)


class Node:
    def __init__(self, path, name=None, metadata=None):
        self.path = path
        self.name = lossy(name if name is not None else os.path.basename(os.path.normpath(path)))
        self.display = lossy(name if name is not None else path)
        self.st = metadata if metadata is not None else os.lstat(path)
        self.typ = node_type(self.st.st_mode)
        self._btime = False
        self.children = []

    def btime(self):
        if self._btime is False:
            self._btime = birth_time(self.path)
        return self._btime

    def sort_key(self, basis):
        st = self.st
        if basis == 'name': return self.name
        if basis == 'cname': return canonical_name(self.name)
        if basis == 'ext': return extension(self.name)
        if basis == 'typ': return TYPE_ORDER[self.typ]
        if basis == 'cat': return 0 if self.typ == 'dir' else 1
        if basis in ('ino','inode'): return st.st_ino
        if basis in ('nlink','nlinks'): return st.st_nlink
        if basis == 'dev': return st.st_dev
        if basis == 'size': return st.st_size
        if basis == 'blocks': return st.st_blocks
        if basis == 'user': return user_name(st.st_uid)
        if basis == 'uid': return st.st_uid
        if basis == 'group': return group_name(st.st_gid)
        if basis == 'gid': return st.st_gid
        if basis == 'btime':
            value = self.btime()
            return (value is not None, value or 0)
        if basis in ('ctime','mtime','atime'): return getattr(st, 'st_'+basis+'_ns')
        return 0


def sort_nodes(nodes, bases):
    # Stable passes, starting at the least significant key.
    for base in reversed(bases):
        reverse = base.endswith('_')
        field = base[:-1] if reverse else base
        nodes.sort(key=lambda node: node.sort_key(field), reverse=reverse)


def os_error(error):
    return os.strerror(error.errno) + ' (os error ' + str(error.errno) + ')'


HEADERS = {
    'dev':'Device','ino':'inode','nlink':'Link#','typ':'T','perm':'Permissions','oct':'SUGO',
    'user':'User','uid':'UID','group':'Group','gid':'GID','size':'Size','blocks':'Blocks',
    'btime':'Created','ctime':'Changed','mtime':'Modified','atime':'Accessed','git':'Git',
}
NUMERIC = {'dev','ino','nlink','oct','uid','gid','size','blocks'}


class Renderer:
    def __init__(self, options):
        self.options = options
        self.color = use_color(1)
        self.grid = options['grid'] and not options['det']

    def c(self, text, codes):
        return paint(text, codes, self.color)

    def name_style(self, node, importance_override=None):
        imp = effective_importance(node.name, self.options['imp']) if importance_override is None else importance_override
        codes = []
        if imp <= -1: codes.append('2')
        elif imp == 1: codes.append('3')
        elif imp >= 2: codes.append('4')
        if node.typ == 'dir': codes.append('34')
        return codes

    def name(self, node, align=True):
        op = self.options
        imp = effective_importance(node.name, op['imp'])
        codes = self.name_style(node)
        result = ''
        if op['icon']:
            icon_codes = (['2'] if imp <= -1 else []) + (['34'] if node.typ == 'dir' else [])
            result += self.c(icon_for(node.name, node.typ) + ' ', ';'.join(icon_codes))
        name = node.display
        if align:
            if op['align'] and not name.startswith('.'):
                result += ' '
            if name.startswith('.'):
                result += self.c('.', '2')
                name = name[1:]
        result += self.c(name, ';'.join(codes))
        if op['suffix']:
            suffix = TYPE_SUFFIX.get(node.typ, '')
            suffix_codes = ['2'] + [s for s in codes if s != '2']
            result += self.c(suffix, ';'.join(suffix_codes))
        if node.typ == 'symlink' and op['sym'] and not self.grid:
            try:
                target = os.readlink(node.path)
                # A relative target is resolved relative to the link, never cwd.
                destination = os.path.join(os.path.dirname(node.path), target)
                try:
                    dst_stat = os.stat(destination)
                    target_color = '34' if stat.S_ISDIR(dst_stat.st_mode) else ''
                    result += ' ' + self.c('\U000f0054','35') + ' ' + self.c(lossy(target),target_color)
                except OSError:
                    result += ' ' + self.c('\U000f17a3 ','31') + self.c(lossy(target),'9;31')
            except OSError:
                pass
        return result

    def permissions(self, mode):
        permissions = stat.filemode(mode)[1:]
        codes = {'r':'33','w':'31','x':'32','-':'2','s':'35','S':'35','t':'35','T':'35'}
        result = ''
        for i, char in enumerate(permissions):
            if i and i % 3 == 0:
                result += ' '
            result += self.c(char,codes[char])
        return result

    def octal(self, mode):
        value = format(mode & 0o7777, '03o')
        codes = ['35', '34', '2;34', '2'][-len(value):]
        return ''.join(self.c(ch,co) for ch,co in zip(value,codes))

    def size(self, size):
        unit = self.options['unit']
        if unit == 'none':
            return self.c(str(size),'1') + ' ' + self.c('B','2')
        step = 1024 if unit == 'binary' else 1000
        powers = ['', 'Ki','Mi','Gi','Ti','Pi','Ei','Zi','Yi'] if unit=='binary' else ['', 'k','M','G','T','P','E','Z','Y']
        power = 0
        number = float(size)
        while number >= step and power < len(powers)-1:
            number /= step
            power += 1
        prefix = powers[power]
        number_str = format(number,'.1f')
        unit_str = prefix + self.c('B','2')
        unit_str = ' ' * ((3 if unit=='binary' else 2) - len(prefix)-1) + unit_str
        return self.c(number_str,'1') + ' ' + unit_str

    def timestamp(self, stamp, field):
        if stamp is None:
            return ''
        try:
            t = time.localtime(stamp // 1000000000)
            months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
            date = f'{t.tm_year:04d}-{months[t.tm_mon-1]}-{t.tm_mday:02d}'
            clock = f'{(t.tm_hour % 12) or 12:02d}:{t.tm_min:02d}' + ('am' if t.tm_hour<12 else 'pm')
            code = '1;' + {'btime':'32','ctime':'33','mtime':'33','atime':'34'}[field]
            return self.c(date, code) + ' ' + clock
        except (ValueError, OSError, OverflowError):
            return ''

    def value(self, node, field):
        st = node.st
        if field == 'dev': return str(st.st_dev)
        if field == 'ino': return str(st.st_ino)
        if field == 'nlink': return str(st.st_nlink)
        if field == 'typ':
            code = '34' if node.typ=='dir' else ('2' if node.typ=='file' else '')
            return self.c(TYPE_LETTER[node.typ],code)
        if field == 'perm': return self.permissions(st.st_mode)
        if field == 'oct': return self.octal(st.st_mode)
        if field in ('user','uid'):
            value = user_name(st.st_uid) if field=='user' else str(st.st_uid)
            return self.c(value, '1;34' if st.st_uid == os.getuid() else '2')
        if field in ('group','gid'):
            value = group_name(st.st_gid) if field=='group' else str(st.st_gid)
            return self.c(value,'2')
        if field == 'size': return '' if node.typ=='dir' else self.size(st.st_size)
        if field == 'blocks': return '' if node.typ=='dir' else str(st.st_blocks)
        if field == 'btime': return self.timestamp(node.btime(),field)
        if field in ('ctime','mtime','atime'): return self.timestamp(getattr(st,'st_'+field+'_ns'),field)
        if field == 'git': return ''
        return ''

    def render_grid(self, names):
        if not names:
            return ''
        width = term_width()
        maxwidth = max(visible_width(name) for name in names)
        n = len(names)
        maxcols = max(1, (width+2) // (maxwidth+2))
        rows = math.ceil(n/maxcols)
        cols = math.ceil(n/rows)
        if cols <= 1:
            return ''.join(name+'\n' for name in names)
        result = ''
        for row in range(rows):
            cells = []
            for col in range(cols):
                index = col*rows+row if self.options['down'] else row*cols+col
                if index < n:
                    cells.append(pad(names[index],maxwidth))
            result += '  '.join(cells) + '\n'
        return result

    def render(self, nodes, directory=False):
        fields = self.options['det']
        names = []
        allnodes = []
        for node in nodes:
            allnodes.append(node)
            names.append(self.name(node, directory))
            for child in node.children:
                allnodes.append(child)
                indent = ('   ' if self.options['align'] else '  ') + '└─ '
                names.append(indent + self.name(child,directory))
        if self.grid:
            return self.render_grid(names)
        if not fields:
            return ''.join(name+'\n' for name in names)
        show_header = self.options['header']
        data = [[self.value(node,field) for field in fields] for node in allnodes]
        widths = [len(HEADERS[f]) if show_header else 0 for f in fields]
        for row in data:
            for i,cell in enumerate(row):
                widths[i] = max(widths[i],visible_width(cell))
        out = ''
        if show_header:
            for i,field in enumerate(fields):
                label = pad(HEADERS[field],widths[i],field in NUMERIC) + ' '
                out += self.c(label, '1;4;3')
            out += self.c('Name', '1;4;3') + '\n'
        for row,name in zip(data,names):
            out += ''.join(pad(value,widths[i],fields[i] in NUMERIC)+' ' for i,value in enumerate(row))
            out += name + '\n'
        return out

    def directory(self, path):
        opts = self.options
        nodes = []
        try:
            entries = os.scandir(path)
        except OSError as err:
            return self.c('error:','1;31') + ' ' + os_error(err) + '\n'
        with entries:
            for entry in entries:
                try:
                    node = Node(entry.path,entry.name,entry.stat(follow_symlinks=False))
                except OSError:
                    continue
                if node.typ not in opts['typ']:
                    continue
                if effective_importance(node.name,opts['imp']) < -1:
                    continue
                if opts.get('exclude') and opts['exclude'].search(node.name):
                    continue
                if opts.get('only') and not opts['only'].search(node.name):
                    continue
                nodes.append(node)
        sort_nodes(nodes,opts['sort'])
        if opts['collapse'] and not self.grid:
            principal = next((node for node in nodes if node.name=='Cargo.toml'),None)
            dependent = next((node for node in nodes if node.name=='Cargo.lock'),None)
            if principal is not None and dependent is not None:
                nodes.remove(dependent)
                principal.children.append(dependent)
        return self.render(nodes,True)

    def run(self, paths):
        files = []
        dirs = []
        out = ''
        for path in paths:
            try:
                node = Node(path)
                if node.typ == 'dir':
                    dirs.append(path)
                else:
                    files.append(node)
            except OSError as err:
                out += self.c(lossy(path),'1') + ':\n\t' + self.c('error:','1;31') + ' ' + os_error(err) + '\n'
        if files:
            out += self.render(files,False)
        for directory in dirs:
            if len(paths)>1:
                out += '\n' + self.c(lossy(directory)+':','1') + '\n'
            out += self.directory(directory)
        return out
