import re
import unicodedata


class RegexError(Exception):
    def __init__(self, pattern, pos=0, length=1, message='', second=None, raw=False):
        if raw:
            self.message = message
            return
        marks = ' '*pos + '^'*max(1,length)
        if second is not None:
            p, n = second
            marks += ' '*max(0,p-len(marks)) + '^'*max(1,n)
        self.message = 'regex parse error:\n    ' + pattern + '\n    ' + marks + '\nerror: ' + message


def normalize(ranges):
    result = []
    for start,end in sorted(ranges):
        if start > end:
            continue
        if result and start <= result[-1][1]+1:
            result[-1] = result[-1][0], max(end,result[-1][1])
        else:
            result.append((start,end))
    return result


def intersection(a,b):
    result=[]
    i=j=0
    while i<len(a) and j<len(b):
        start,end=max(a[i][0],b[j][0]),min(a[i][1],b[j][1])
        if start<=end: result.append((start,end))
        if a[i][1]<b[j][1]: i+=1
        else: j+=1
    return result


def difference(a,b):
    result=[]
    j=0
    for start,end in a:
        while j<len(b) and b[j][1]<start: j+=1
        k=j
        while k<len(b) and b[k][0]<=end:
            if start < b[k][0]: result.append((start,b[k][0]-1))
            start=max(start,b[k][1]+1)
            k+=1
        if start<=end: result.append((start,end))
    return result


SCALARS=[(0,0xd7ff),(0xe000,0x10ffff)]
BYTE=[(0,255)]
SPACE=[(9,13),(32,32)]
UNICODE_SPACE=SPACE+[(0x85,0x85),(0xa0,0xa0),(0x1680,0x1680),(0x2000,0x200a),
                     (0x2028,0x2029),(0x202f,0x202f),(0x205f,0x205f),(0x3000,0x3000)]
