    'alnum':[(48,57),(65,90),(97,122)], 'alpha':[(65,90),(97,122)],
    'ascii':[(0,127)], 'blank':[(9,9),(32,32)], 'cntrl':[(0,31),(127,127)],
    'digit':[(48,57)], 'graph':[(33,126)], 'lower':[(97,122)],
    'print':[(32,126)], 'punct':[(33,47),(58,64),(91,96),(123,126)],
    'space':SPACE, 'upper':[(65,90)], 'word':[(48,57),(65,90),(95,95),(97,122)],
    'xdigit':[(48,57),(65,70),(97,102)],
}


@functools.lru_cache(maxsize=40)
def unicode_property(name):
    key=re.sub(r'[ _-]','',name).lower()
    if '=' in key:
        kind,key=key.split('=',1)
        if kind not in ('gc','generalcategory','sc','script','scx','scriptextensions'):
            return None
    aliases={
        'letter':'l','uppercaseletter':'lu','lowercaseletter':'ll','titlecaseletter':'lt',
        'modifierletter':'lm','otherletter':'lo','mark':'m','nonspacingmark':'mn',
        'spacingmark':'mc','spacingcombiningmark':'mc','enclosingmark':'me',
        'number':'n','decimalnumber':'nd','decimaldigitnumber':'nd','letternumber':'nl','othernumber':'no',
        'punctuation':'p','connectorpunctuation':'pc','dashpunctuation':'pd','openpunctuation':'ps',
        'closepunctuation':'pe','initialpunctuation':'pi','finalpunctuation':'pf','otherpunctuation':'po',
        'symbol':'s','mathsymbol':'sm','currencysymbol':'sc','modifiersymbol':'sk','othersymbol':'so',
        'separator':'z','spaceseparator':'zs','lineseparator':'zl','paragraphseparator':'zp',
        'other':'c','control':'cc','format':'cf','privateuse':'co','surrogate':'cs','unassigned':'cn',
    }
    key=aliases.get(key,key)
    if key in ('ascii',): return [(0,127)]
    if key in ('any',): return SCALARS[:]
