        'cyrillic':[(0x400,0x52f),(0x2de0,0x2dff),(0xa640,0xa69f)],
        'latin':[(65,90),(97,122),(0xc0,0x2e4),(0x1d00,0x1d7f),(0x1e00,0x1eff),(0xab30,0xab6f)],
