    if not ranges: return []
    starts=[a for a,b in ranges]
    def contains(cp):
        i=bisect.bisect_right(starts,cp)-1
        return i>=0 and cp<=ranges[i][1]
    more=[]
    groups=unicode_case_groups() if unicode else [{n,n+32} for n in range(65,91)]
    for group in groups:
        if any(contains(n) for n in group):
            more.extend((n,n) for n in group)
    return normalize(ranges+more)


def byte_class(lo,hi):
    if lo==hi: return '\\x%02x'%lo
    return '[\\x%02x-\\x%02x]'%(lo,hi)


def utf8_range(low,high):
    """Regex alternatives for the lexicographic interval of UTF-8 sequences."""
    if len(low)==1:
        return [byte_class(low[0],high[0])]
    if low[0]==high[0]:
        return [byte_class(low[0],low[0])+s for s in utf8_range(low[1:],high[1:])]
    n=len(low)-1
    minimum=bytes([0x80])*n
    maximum=bytes([0xbf])*n
    if low[1:]==minimum and high[1:]==maximum:
        return [byte_class(low[0],high[0])+byte_class(0x80,0xbf)*n]
    result=[byte_class(low[0],low[0])+s for s in utf8_range(low[1:],maximum)]
    if low[0]+1<=high[0]-1:
        result.append(byte_class(low[0]+1,high[0]-1)+byte_class(0x80,0xbf)*n)
