        if self.peek()=='\\':
            kind,value,byte=self.escape(flags,True)
            if kind=='set':return self.fold(value,flags),None,start
            return self.fold([(value,value)],flags),value,start
        c=self.peek();self.i+=1
        if ord(c)>127 and 'u' not in flags:self.error(start,1,'Unicode not allowed here')
