                self.error(start,3,'look-around, including look-ahead and look-behind, is not supported')
            if self.pattern[self.i:self.i+2] in ('<=','<!'):
                self.error(start,4,'look-around, including look-ahead and look-behind, is not supported')
            if self.pattern.startswith('P<',self.i) or self.peek()=='<':
                self.i+=2 if self.peek()=='P' else 1
