                choices.append(''.join(atoms));atoms=[];self.i+=1;continue
            if ch in '*+?{':self.error(self.i,1,'repetition operator missing expression')
            if ch=='(':
                atom=self.group(flags)
                if atom is None:continue
            elif ch=='[':
                atom=set_pattern(self.character_class(flags),'u' in flags)
            elif ch=='\\':
                kind,value,byte=self.escape(flags)
                atom=value if kind=='expr' else (set_pattern(self.fold(value,flags),'u' in flags) if kind=='set' else self.literal(value,flags,byte))
