def regex_compile(pattern):
    translator=Translator(pattern)
    translated=translator.expression(set())
    try:
        compiled=re.compile(translated.encode('ascii'))
    except (re.error,OverflowError,RecursionError) as err:
        raise RegexError(pattern,message='Compiled regex exceeds size limit of 10485760 bytes.',raw=True) from err
    return Pattern(compiled)
